from typing import Protocol, Dict, Any, List, Optional, Sequence
from dataclasses import dataclass
from pathlib import Path

@dataclass(frozen=True)
class ExperimentResult:
    """Container for the outputs generated by a reproduction experiment."""
    experiment_id: str
    success: bool
    metrics: Dict[str, Any]  # Key quantity checks (e.g., mean squared velocity)
    artifacts: Dict[str, str] # Map of artifact names to file paths (plots, tables)
    errors: Optional[List[str]] = None

class Experiment(Protocol):
    """Contract for experiment modules (EXP1-EXP5)."""
    def execute(self) -> ExperimentResult:
        """Performs the reproduction logic, saves artifacts, and returns metrics."""
        ...


@dataclass(frozen=True)
class BatchReproductionSuite:
    """
    Consolidated container for the results of a complete reproduction batch (EXP1-EXP5).
    
    This suite aggregates individual ExperimentResult objects, maintaining the 
    mapping of experiment IDs to their respective metrics, persistent artifacts 
    (plots/tables), and execution status.
    
    Attributes:
        results: Mapping of experiment IDs ('EXP1', 'EXP2', 'EXP3', 'EXP4', 'EXP5') to results.
        output_directory: The root path where generated artifacts like 'anisotropy_ratio.png' 
                         and 'residence_times.csv' are stored.
        execution_order: The sequence in which experiments were processed to ensure 
                         DS2 availability for diagnostic steps.
    """
    results: Dict[str, ExperimentResult]
    output_directory: Path
    execution_order: List[str]


class BatchExperimentOrchestrator:
    """
    Coordinates the end-to-end execution of the reproduction pipeline for solenoidal turbulence.
    
    This orchestrator ensures that the Lagrangian tracer trajectory dataset (DS2) is 
    generated via EXP1 using the 4th-order Runge-Kutta (RK4) integrator before 
    launching downstream analyses.
    
    Workflow Managed:
    1. EXP1: Tracer Trajectory Generation (Produces DS2).
    2. EXP2: Anisotropic Dispersion Analysis (Calculates lambda(t) vs target 0.52).
    3. EXP3: Vortex Residence Time Calculation (Quantifies tau_Q / Te vs target 0.077).
    4. EXP4: Displacement PDF Evolution (Evaluates platykurtic behavior and Hill index).
    5. EXP5: FTLE and Chaos Analysis (Cohort comparison of trapped vs free tracers).
    """

    def __init__(self, output_root: Path):
        """
        Initializes the orchestrator with a workspace for artifacts.
        
        Args:
            output_root: Directory where all experiment artifacts (JSON_metrics, 
                png_plots, csv_tables, markdown_tables) will be saved.
        """
        self.output_root = Path(output_root)
        self.output_root.mkdir(parents=True, exist_ok=True)

    def run_batch(self, experiments: Sequence[Experiment]) -> BatchReproductionSuite:
        """
        Executes all reproduction experiments in the correct dependency sequence.
        
        Logic verifies that EXP1 (dx/dt = v(x(t), t)) completes successfully before 
        attempting analyses (EXP2-EXP5) that rely on the resulting tracer state vectors.
        
        Args:
            experiments: A sequence of configured Experiment objects representing EXP1 through EXP5.
            
        Returns:
            A BatchReproductionSuite containing results and verification metrics for all claims (C1-C4).
            
        Raises:
            RuntimeError: If a mandatory experiment dependency fails (e.g., failed trajectory generation).
        """
        results: Dict[str, ExperimentResult] = {}
        execution_order: List[str] = []
        
        exp1_success = False
        
        for exp in experiments:
            res = exp.execute()
            results[res.experiment_id] = res
            execution_order.append(res.experiment_id)
            
            if res.experiment_id == "EXP1":
                if not res.success:
                    errors_msg = "; ".join(res.errors) if res.errors else "Unknown error"
                    raise RuntimeError(f"EXP1 failed: {errors_msg}. Cannot proceed with downstream analysis.")
                exp1_success = True
            
            elif res.experiment_id in ["EXP2", "EXP3", "EXP4", "EXP5"]:
                if not exp1_success:
                    raise RuntimeError(f"Experiment {res.experiment_id} requires successful completion of EXP1.")
        
        return BatchReproductionSuite(
            results=results,
            output_directory=self.output_root,
            execution_order=execution_order
        )

    def verify_suite_targets(self, suite_results: BatchReproductionSuite) -> Dict[str, bool]:
        """
        Benchmarks the batch results against the paper's analytical specifications.
        
        Specifications Checked:
        - lambda(t) convergence toward 0.52 (Claim C1).
        - tau_Q / Te ratio approximately 0.077 (Claim C2).
        - Gaussianity at t=2.0 and platykurtic behavior at late times (Claim C3).
        - FTLE distribution similarity between trapped/free cohorts (Claim C4).
        
        Args:
            suite_results: The results from a completed batch execution.
            
        Returns:
            A dictionary mapping claim IDs or experiment labels to a boolean pass/fail status.
        """
        verifications: Dict[str, bool] = {
            "C1": False,
            "C2": False,
            "C3": False,
            "C4": False
        }
        
        res_map = suite_results.results
        
        # Claim C1: Anisotropy ratio (EXP2)
        if "EXP2" in res_map and res_map["EXP2"].success:
            m = res_map["EXP2"].metrics
            val = m.get("mean_lambda_late", 0.0)
            target = m.get("target_lambda", 0.52)
            # Check if within 20%
            verifications["C1"] = abs(val - target) < 0.2 * target
            
        # Claim C2: Vortex residence time (EXP3)
        if "EXP3" in res_map and res_map["EXP3"].success:
            m = res_map["EXP3"].metrics
            val = m.get("ratio_tau_te", 0.0)
            target = m.get("target_ratio", 0.077)
            # Check if within 20%
            verifications["C2"] = abs(val - target) < 0.2 * target
            
        # Claim C3: PDF evolution (EXP4)
        if "EXP4" in res_map and res_map["EXP4"].success:
            m = res_map["EXP4"].metrics
            ks_p = m.get("ks_p_value_t2", 0.0)
            kurt_t5 = m.get("excess_kurtosis_t5", 0.0)
            kurt_t9 = m.get("excess_kurtosis_t9", 0.0)
            
            # Normal distribution if p-value is not too small (alpha=0.01)
            # Platykurtic if excess kurtosis < 0
            verifications["C3"] = (ks_p > 0.01) and (kurt_t5 < 0) and (kurt_t9 < 0)
            
        # Claim C4: FTLE similarity (EXP5)
        if "EXP5" in res_map and res_map["EXP5"].success:
            m = res_map["EXP5"].metrics
            t_mean = m.get("trapped_mean_ftle", 0.0)
            f_mean = m.get("free_mean_ftle", 1.0)
            
            # Similarity check: within 30%
            if f_mean != 0:
                verifications["C4"] = abs(t_mean - f_mean) / f_mean < 0.3
                
        return verifications
